// A granted package that shares a *narrowed* slice of its authority. It holds
// fs:read on the whole ./shared tree (via the policy artifact) and mints a
// handle scoped to ./shared/pub -- the attenuated capability it hands across
// the package boundary.

export function makeShareHandle() {
  // Frame-checked mint: grantor holds fs:read:./shared, so minting the narrower
  // fs:read:./shared/pub succeeds.
  return Deno.oden.mint("fs:read:./shared/pub");
}

export function tryMintTooWide() {
  // grantor does NOT hold ./elsewhere, so this mint exceeds its holding and is
  // denied (a mint cannot exceed what the minter holds).
  return Deno.oden.mint("fs:read:./elsewhere");
}

export function revoke(handle) {
  // Revoke through the grantor's frame so the audit attributes it to grantor.
  handle.revoke();
}
